local SettingRefBase = require('Game.Setting.SettingRefBase')
---@class CardTalentVo
local CardTalentVo = Class("CardTalentVo", SettingRefBase)

local base = SettingRefBase
local ParseUtils = CS.ParseUtils
local parse_string = parse_string
local parse_number = parse_number
local parse_strings = parse_strings
local checkNumber = checkNumber
local parse_localizeText = parse_localizeText

function CardTalentVo:__init()
    self.id = 0
    self.pos = 0
    self.type = 0
    self.roleId = 0
    self.attrAdditions = nil
    self.passive = nil
    self.exPassive = nil
    self.icon = ""
    self.groupId = 0
    self.name = ""
    self.desc = ""
    self.costRewards = nil
end

function CardTalentVo:__delete()
    self.id = nil
    self.pos = nil
    self.type = nil
    self.roleId = nil
    self.attrAdditions = nil
    self.passive = nil
    self.exPassive = nil
    self.exStar = nil
    self.icon = nil
    self.groupId = nil
    self.costRewards = nil
end

---FillVo
---@param row TableML.TableFileRow
function CardTalentVo:FillVo(row)
    base.FillVo(self, row)

    self.id     = parse_number(row, "id")
    self.pos    = parse_number(row, "pos")
    ---Constants.CultivateCardTalentPointType
    self.type   = parse_number(row, "type")
    self.roleId = parse_number(row, "roleId")
    --- 替换id
    self.exId = parse_number(row, "exId")

    self.name = parse_localizeText(row, "name")
    self.desc = parse_localizeText(row, "desc", true)

    --- 属性加成  {{id = id, num = num}}
    self.attrAdditions = self:ParseIdAndNumList(row, "attAddTypeId", "attAddNum")
    --- 被动 {{id = id, num = star}}
    self.passive       = self:ParseIdAndNumList(row, "addBuffId", "star")
    --- 替换被动技能 {{id = id, num = star}}
    self.exPassive     = self:ParseIdAndNumList(row, "exBuffId", "exStar")

    self.icon = ParseUtils.ParsePathName(row, "icon")

    self.groupId =  parse_number(row, "groupId")

    self.costRewards   = parse_rewards(parse_string(row, "costItem"), parse_string(row, "costNum"))

end

function CardTalentVo:ParseIdAndNumList(row, idKay, numKey)
    local list = {}
    local str_add = parse_string(row, idKay)
    if not (string.isEmpty(str_add) or str_add == '0') then
        local ids    = parse_strings(str_add)
        local numArr = parse_strings(parse_string(row, numKey))
        local length = math.min(#ids, #numArr)
        for i = 1, length do
            table.insert(list, {
                id   = ids[i],
                num = checkNumber(numArr[i])
            })
        end
    end
    return list
end

return CardTalentVo